-- V40-9A: executable-source configuration inventory governance and migration-ready gate.
-- Generated observation materialization is deterministic. Source-controlled definitions remain the only definition authority.

create table if not exists runtime_config_inventory_observations (
  configuration_key varchar(512) primary key, namespace varchar(128) not null, source_observation_hash char(64) not null,
  current_files jsonb not null, profiles jsonb not null, value_shapes jsonb not null, review_flags jsonb not null,
  mutability_floor varchar(64) not null, source_usage_evidence jsonb not null default '{}'::jsonb,
  advisory_classification jsonb, observed_at timestamptz not null default now(),
  check (source_observation_hash ~ '^[0-9a-f]{64}$')
);
create index if not exists idx_runtime_config_inventory_obs_namespace on runtime_config_inventory_observations(namespace,configuration_key);

create table if not exists runtime_config_inventory_governance (
  configuration_key varchar(512) primary key references runtime_config_inventory_observations(configuration_key),
  status varchar(32) not null default 'DISCOVERED', source_observation_hash char(64) not null,
  domain_owner varchar(128), authority_class varchar(64), scope varchar(64), risk varchar(32), mutability varchar(64), consumer_contract varchar(64),
  admin_editable boolean, requires_approval boolean, classified_by varchar(255), classified_at timestamptz,
  owner_reviewed_by varchar(255), owner_reviewed_at timestamptz, architecture_approved_by varchar(255), architecture_approved_at timestamptz,
  migration_authorized_by varchar(255), migration_authorized_at timestamptz, reason text, version bigint not null default 1, updated_at timestamptz not null default now(),
  check(status in ('DISCOVERED','CLASSIFIED','OWNER_REVIEWED','ARCHITECTURE_APPROVED','MIGRATION_READY','MIGRATED','LEGACY_RETIRED'))
);
create index if not exists idx_runtime_config_inventory_governance_status on runtime_config_inventory_governance(status,configuration_key);

create table if not exists runtime_config_inventory_governance_events (
  event_id bigserial primary key, configuration_key varchar(512) not null references runtime_config_inventory_observations(configuration_key),
  event_type varchar(64) not null, from_status varchar(32), to_status varchar(32) not null, actor varchar(255) not null, reason text not null,
  source_observation_hash char(64) not null, detail_json jsonb not null default '{}'::jsonb, created_at timestamptz not null default now()
);
create index if not exists idx_runtime_config_inventory_events_key on runtime_config_inventory_governance_events(configuration_key,event_id desc);

