insert into runtime_config_inventory_observations(configuration_key,namespace,source_observation_hash,current_files,profiles,value_shapes,review_flags,mutability_floor,source_usage_evidence,advisory_classification)
select key,namespace,"sourceObservationHash","currentFiles",profiles,"valueShapes","reviewFlags","mutabilityFloor",coalesce("sourceUsageEvidence",'{}'::jsonb),"advisoryClassification" from src
on conflict(configuration_key) do update set namespace=excluded.namespace,source_observation_hash=excluded.source_observation_hash,current_files=excluded.current_files,profiles=excluded.profiles,
 value_shapes=excluded.value_shapes,review_flags=excluded.review_flags,mutability_floor=excluded.mutability_floor,source_usage_evidence=excluded.source_usage_evidence,
 advisory_classification=excluded.advisory_classification,observed_at=now();

insert into runtime_config_inventory_governance(configuration_key,status,source_observation_hash,reason)
select configuration_key,'DISCOVERED',source_observation_hash,'V40-9A executable-source materialization' from runtime_config_inventory_observations
on conflict(configuration_key) do update set source_observation_hash=excluded.source_observation_hash,updated_at=now(),
 status=case when runtime_config_inventory_governance.source_observation_hash=excluded.source_observation_hash then runtime_config_inventory_governance.status else 'DISCOVERED' end,
 domain_owner=case when runtime_config_inventory_governance.source_observation_hash=excluded.source_observation_hash then runtime_config_inventory_governance.domain_owner else null end,
